style.css:
@-moz-document domain("chat.openai.com") {
/* Fundo geral de kiwis */
  body {
    background-image: url("https://cdn.pixabay.com/photo/2016/04/14/12/39/kiwi-1324151_1280.jpg");
    background-size: cover;
    background-attachment: fixed;
    background-repeat: no-repeat;
    background-position: center;
    color: #ffffff;
  }

  /* Caixa de mensagens */
  .text-base {
    background-color: rgba(0, 0, 0, 0.5) !important;
    border-radius: 12px;
    padding: 10px;
    backdrop-filter: blur(5px);
  }

  /* Header kiwi */
  header {
    background-color: rgba(0, 0, 0, 0.7) !important;
    backdrop-filter: blur(10px);
    position: relative;
  }

  header::before {
    content: "? KiwiGPT";
    position: absolute;
    left: 20px;
    top: 10px;
    font-weight: 700;
    font-size: 1.2rem;
    color: #fff;
  }

  /* Deixa os botões verdes kiwi */
  button {
    background-color: #6ac24d !important;
    color: #fff !important;
    border-radius: 10px !important;
  }

  button:hover {
    background-color: #57a53e !important;
  }

  /* Remove sombra de fundo que atrapalha o kiwi */
  .bg-token-surface-primary {
    background: transparent !important;
  }

  .bg-token-surface-secondary {
    background: rgba(0, 0, 0, 0.3) !important;
  }
}
